<?php
namespace App\Http\Controllers\Public\Business\Public\Ecommerce\Account\Orders;
use App\Http\Controllers\Controller;
use App\Services\Public\Business\Admin\Ecommerce\OnlineOrders\OnlineOrderList\OnlineOrderService;
use App\Services\Public\Business\Admin\Ecommerce\OnlineOrders\ReturnRequests\ReturnRequestService;
use App\Models\Ecommerce\ReturnRequest;
use Illuminate\Http\Request;
class OrdersController extends Controller {
 public function index(Request $r,OnlineOrderService $s){ $customer=$r->user('business_customer');$q=$s->customer($r->attributes->get('current_business'),$customer->id);if($r->filled('q'))$q->where('order_no','like','%'.mb_substr($r->query('q'),0,80).'%');if(in_array($r->query('delivery'),['pending','packed','shipped','delivered'],true))$q->where('delivery_status',$r->query('delivery'));$orders=$q->latest('id')->paginate(12)->withQueryString();return view('public.business.public.ecommerce.account.orders',compact('customer','orders')); }
 public function show(Request $r,string $business,int $order,OnlineOrderService $s){ $customer=$r->user('business_customer');$b=$r->attributes->get('current_business');$order=$s->customer($b,$customer->id)->with(['items'=>fn($q)=>$q->where('business_id',$b->id)])->findOrFail($order);$requests=ReturnRequest::where('business_id',$b->id)->where('customer_id',$customer->id)->where('order_id',$order->id)->latest('id')->get(); $cancellations=\App\Models\Ecommerce\CancellationRequest::where('business_id',$b->id)->where('customer_id',$customer->id)->where('order_id',$order->id)->latest('id')->get();$canCancel=app(\App\Services\Public\Business\Admin\Ecommerce\OnlineOrders\OnlineOrderList\CancellationRequestService::class)->eligible($order);$shipments=\App\Models\Retail\CourierShipment::where('business_id',$b->id)->where('order_id',$order->id)->get(['provider','status','consignment_id','updated_at']);return view('public.business.public.ecommerce.account.order',compact('customer','order','requests','cancellations','canCancel','shipments')); }
 public function requestReturn(Request $r,string $business,int $order,ReturnRequestService $s){ $data=$r->validate(['order_item_id'=>'required|integer','quantity'=>'required|numeric|min:0.001|max:999999|decimal:0,3','reason'=>'required|string|max:255']);$s->submit($r->attributes->get('current_business'),$r->user('business_customer')->id,$order,$data);return back()->with('success',t('Return request submitted.','রিটার্ন অনুরোধ পাঠানো হয়েছে।')); }
 public function receipt(Request $r,string $business,int $order,OnlineOrderService $s){$b=$r->attributes->get('current_business');$order=$s->customer($b,$r->user('business_customer')->id)->with(['items'=>fn($q)=>$q->where('business_id',$b->id)])->findOrFail($order);return view('public.business.public.ecommerce.account.receipt',['business'=>$b,'order'=>$order]);}
 public function returns(Request $r){ $customer=$r->user('business_customer');$requests=ReturnRequest::where('business_id',$r->attributes->get('current_business')->id)->where('customer_id',$customer->id)->latest('id')->paginate(15);return view('public.business.public.ecommerce.account.returns',compact('customer','requests')); }
 public function cancelRequest(Request $r,string $business,int $order,\App\Services\Public\Business\Admin\Ecommerce\OnlineOrders\OnlineOrderList\CancellationRequestService $service){$data=$r->validate(['reason'=>'required|string|max:255']);$service->submit($r->attributes->get('current_business'),$r->user('business_customer')->id,$order,$data['reason']);return back()->with('success',t('Cancellation requested.','বাতিলের অনুরোধ পাঠানো হয়েছে।'));}
 public function buyAgain(Request $r,string $business,int $order,OnlineOrderService $service,\App\Services\Public\Business\Public\Ecommerce\Catalog\Products\CatalogService $catalog){$b=$r->attributes->get('current_business');$customer=$r->user('business_customer');$record=$service->customer($b,$customer->id)->findOrFail($order);$items=$record->items()->where('business_id',$b->id)->get();$products=$catalog->query($b)->whereHas('variants',fn($q)=>$q->whereIn('id',$items->pluck('variant_id')))->get();return view('public.business.public.ecommerce.account.reorder',compact('customer','record','items','products'));}
}
